// Android only: allow cleartext http to localhost when, and only when, the app is
// prebuilt against a local mock HashBin (EXPO_PUBLIC_HASHBIN_API=http://localhost:…,
// spec/hashbin.md "Development"). The native and Flutter ports do the same in their
// debug builds; RN's Maestro runs use Release builds, so this keys off the mock
// variable instead. Normal builds are unchanged.
const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod } = require('expo/config-plugins');

const XML = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/with-mock-cleartext.js for a mock HashBin build only. -->
<network-security-config>
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">localhost</domain>
        <domain includeSubdomains="false">127.0.0.1</domain>
    </domain-config>
</network-security-config>
`;

function usesLocalMock() {
  const urls = [process.env.EXPO_PUBLIC_HASHBIN_API, process.env.EXPO_PUBLIC_HASHBIN_CONTENT];
  return urls.some(u => /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?(\/|$)/.test(u ?? ''));
}

module.exports = function withMockCleartext(config) {
  if (!usesLocalMock()) return config;
  config = withDangerousMod(config, ['android', async c => {
    const dir = path.join(c.modRequest.platformProjectRoot, 'app/src/main/res/xml');
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'mock_network_security_config.xml'), XML);
    return c;
  }]);
  return withAndroidManifest(config, c => {
    c.modResults.manifest.application[0].$['android:networkSecurityConfig'] = '@xml/mock_network_security_config';
    return c;
  });
};
